queries.sphinxql:
create table knn_local (
	embedding float_vector knn_type='hnsw' knn_dims='4' hnsw_similarity='cosine' quantization='1bit'
);
insert into knn_local (id, embedding) values (1, (0.1, 0.2, 0.3, 0.4));

create table knn_remote (
	embedding float_vector knn_type='hnsw' knn_dims='4' hnsw_similarity='cosine' quantization='1bit'
);
insert into knn_remote (id, embedding) values (2, (0.4, 0.3, 0.2, 0.1));

create table knn_dist type='distributed'
	local='knn_local'
	agent=':knn_remote';

show tables like 'knn_dist';
drop table knn_dist;
drop table knn_local;
